#!/usr/bin/env node
/**
 * Bundle client-src/ into the single classic script the host loads:
 * `client/client.js` (a generated artifact — edit client-src, not this output).
 *
 * - IIFE, zero imports left over: the host serves it as a plain <script>.
 * - Classic JSX with factory `h`: React is late-bound inside the module
 *   factory (see client-src/react-binding.ts), so the bundle must not touch
 *   React at module scope — esbuild's `--external:react` cannot be used
 *   because it emits a top-level `__require("react")`.
 * - A `@generated` banner marks the output; `window` and `setInterval` stay
 *   free identifiers so the Node test harness can stub them via
 *   `new Function('window', 'setInterval', source)`.
 */
import { build } from 'esbuild';
import { readFile, writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const root = join(dirname(fileURLToPath(import.meta.url)), '..');
const entry = join(root, 'client-src', 'entry.ts');
const outfile = join(root, 'client', 'client.js');

const result = await build({
  entryPoints: [entry],
  bundle: true,
  format: 'iife',
  outfile,
  jsx: 'transform',
  jsxFactory: 'h',
  target: 'es2022',
  legalComments: 'none',
  sourcemap: false,
  minify: false,
  metafile: true,
  logLevel: 'info',
});

const bytes = (await readFile(outfile, 'utf8')).length;
const generatedBanner = `// @generated by scripts/build-client.mjs — edit client-src/ instead.\n`;
await writeFile(outfile, generatedBanner + (await readFile(outfile, 'utf8')));

const outputs = Object.entries(result.metafile.outputs);
for (const [name, info] of outputs) {
  console.log(`[build-client] ${name.replace(`${root}/`, '')}: ${(info.bytes / 1024).toFixed(1)} KiB`);
}
console.log(`[build-client] client/client.js total: ${(bytes / 1024).toFixed(1)} KiB (IIFE, classic JSX factory h, React late-bound)`);
